	'messages:uploaded-wrong-setting-svg' => 'awa:"set" का उपयोग कर किसी अन्य डाटा, लिपि से कार्य अवरोधित है। एसवीजी फ़ाइल में मिला <code>&lt;set to="$1"&gt;</code> है।',
	'messages:uploaded-setting-handler-svg' => 'awa:एसवीजी जो "handler" जोड़ता है, अवरोधित है। उससे मिला <code>$1="$2"</code> है।',
	'messages:uploaded-remote-url-svg' => 'awa:एसवीजी जो रिमोट पते द्वारा शैली तय करता है, अवरोधित है। उससे <code>$1="$2"</code> मिला है।',
