	'messages:config-no-cli-uri' => 'hi:<strong>चेतावनी:</strong> कोई <code>--scriptpath</code> निर्दिष्ट नहीं किया गया है, डिफ़ॉल्ट का इस्तेमाल किया जा रहा है: <code>$1</code>।',
	'messages:config-using-server' => 'hi:सर्वर के नाम"<nowiki>$1</nowiki>" का इस्तेमाल किया जा रहा है।',
